// [Dense GroupBy Sum 最適化] x & 15 の小範囲キー(0..15)を stackalloc 直結テーブルで集約。
// キー範囲不明時は ArrayPool.Shared.Rent による開放番地法テーブルでヒープ割当 0B 化可能。
if(raw.Length==0)return 0L;
Span<int> sums=stackalloc int[16];
Span<byte> seen=stackalloc byte[16];
Span<byte> order=stackalloc byte[16];
int groupCount=0;
for(var i=0;i<raw.Length;i++){
    var x=raw[i];
    var k=x&15;
    if(seen[k]==0){
        seen[k]=1;
        order[groupCount++]=(byte)k;
    }
    sums[k]+=x;
}
var total=0L;
for(var i=0;i<groupCount;i++){
    var k=order[i];
    total+=(long)(k+sums[k]);
}
return total;

