// A.B(OrderBy->Where Pushdown) + B.C(Where->Select) + C.D(Select->FirstOrDefault) => 偶数のみから最小キー要素を1パス選択
var found=false;
var bestVal=0;
var bestKey=int.MaxValue;
for(var i=0;i<raw.Length;i++){
    var x=raw[i];
    if((x&1)==0){
        var k=x&31;
        if(!found||k<bestKey){
            found=true;
            bestKey=k;
            bestVal=x*3+1;
        }
    }
}
if(found){
    return bestVal;
}else{
    return 0;
}

Span<int> sums=stackalloc int[16];
Span<byte> seen=stackalloc byte[16];
Span<byte> order=stackalloc byte[16];
int groupCount=0;
for(var i=0;i<raw.Length;i++){
    var x=raw[i];
    var k=x&15;
    if(seen[k]==0){
        seen[k]=1;
        order[groupCount++]=(byte)k;
    }
    sums[k]+=x;
}
if(groupCount==0)return System.Array.Empty<int>();
Span<int> values=stackalloc int[groupCount];
Span<int> sortKeys=stackalloc int[groupCount];
Span<int> indexes=stackalloc int[groupCount];
for(var i=0;i<groupCount;i++){
    var k=order[i];
    var val=k+sums[k];
    values[i]=val;
    sortKeys[i]=val&31;
    indexes[i]=i;
}
for(var i=1;i<groupCount;i++){
    var currIdx=indexes[i];
    var currKey=sortKeys[currIdx];
    var j=i-1;
    while(j>=0&&sortKeys[indexes[j]]<currKey){
        indexes[j+1]=indexes[j];
        j--;
    }
    indexes[j+1]=currIdx;
}
var takeCount=System.Math.Min(groupCount,12);
var result=System.GC.AllocateUninitializedArray<int>(takeCount);
for(var i=0;i<takeCount;i++){
    result[i]=values[indexes[i]];
}
return result;

